// `just naming-consent-hashes` — [OPERATOR] local-only step.
//
// Regenerates src/lib/naming-consent.hashes.json (COMMITTED, tracked) from
// ~/.gftb/naming-consent.plain (NEVER committed — lives outside every repo,
// gitignored-by-location: it simply is not inside any git working tree),
// keyed by ~/.gftb/naming-consent.key (also never committed; generated by
// this script on first run if absent).
//
// WHY THIS EXISTS (see docs/runbooks/discuss-to-svx-pipeline.md, "Naming-
// consent gate design", for the full incident writeup): an earlier version
// of this pipeline enforced naming consent with a literal denylist,
// committed in plaintext directly in application code — blocked before
// merge. The v1 fix (this script's first version) replaced that with
// per-token SALTED SHA-256, hashes committed next to their salt. That was
// also wrong: salt defeats precomputed rainbow tables, not guessing, and
// review recovered both protected tokens in single-digit milliseconds from
// a stock OS dictionary. A committed salted-hash list of short tokens is a
// RECOVERY oracle, not a confirmation oracle.
//
// v2 (this version) uses KEYED HMAC-SHA256 instead: the committed file
// holds HMAC digests only, generated with a 32-byte key that never enters
// any git tree. Without the key, the committed file is cryptographically
// inert — there is nothing to guess against. It also commits no per-token
// length (the v1 file did; that leaked the shape of the protected-token
// set for no real benefit) — src/lib/naming-consent.ts's scanner sweeps a
// fixed window range instead.
//
// Because HMAC generation is deterministic (same plaintext + same key =
// same digest, unlike v1's fresh-random-salt-per-run), regenerating from an
// unchanged plaintext file reproduces the committed file byte-for-byte.
// That determinism is what makes scripts/verify-naming-consent-hashes.mjs
// (the drift gate, `just naming-consent-hashes-verify`) possible at all.
//
// USAGE
//   just naming-consent-hashes
//   # or directly:
//   node scripts/generate-naming-consent-hashes.mjs
//
// INPUT
//   ~/.gftb/naming-consent.plain — one protected token per line. Blank
//     lines and lines starting with `#` are ignored. Put every form that
//     must never appear in public copy on its own line: full name,
//     nicknames, suffixed/surname-shaped forms, etc. Tokens shorter than
//     naming-consent.ts's MIN_TOKEN_LENGTH (4, after normalization) are
//     REJECTED here rather than silently enrolled uselessly — see that
//     module and the runbook for why (a 1-character token flags 375 of the
//     384 files tracked in this repo; it is not enforceable this way).
//     Route bare-initial forms to editorial review instead.
//   ~/.gftb/naming-consent.key — 64 lowercase hex characters (32 bytes).
//     Created automatically, mode 0600, if this file does not already
//     exist. NEVER regenerated once created without deliberate operator
//     action: doing so silently invalidates every previously committed
//     digest (nothing will match the old key's output anymore).
//
// OUTPUT  src/lib/naming-consent.hashes.json (tracked, committed)
//   A sorted, deduplicated JSON array of 64-hex-char HMAC-SHA256 digests.
//   No plaintext, no length, no salt — just opaque digests.
import { randomBytes } from 'node:crypto';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
	buildHashList,
	KEY_FILE,
	MIN_TOKEN_LENGTH,
	normalizeForConsent,
	PLAIN_FILE,
} from '../src/lib/naming-consent.ts';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const OUT_FILE = path.join(ROOT, 'src', 'lib', 'naming-consent.hashes.json');

async function loadOrCreateKey() {
	try {
		const raw = (await fs.readFile(KEY_FILE, 'utf8')).trim();
		if (!/^[0-9a-f]{64}$/i.test(raw)) {
			throw new Error(
				`${KEY_FILE} exists but is not 64 hex characters. Fix or remove it (this will invalidate the committed hash list) and re-run.`,
			);
		}
		return Buffer.from(raw, 'hex');
	} catch (error) {
		if (error?.code !== 'ENOENT') throw error;
	}
	const key = randomBytes(32);
	await fs.mkdir(path.dirname(KEY_FILE), { recursive: true });
	await fs.writeFile(KEY_FILE, `${key.toString('hex')}\n`, { mode: 0o600 });
	console.log(`generated a new key at ${KEY_FILE} (mode 0600). Back it up — losing it means every`);
	console.log('committed digest becomes unmatchable and the hash list must be fully regenerated.');
	return key;
}

async function main() {
	const key = await loadOrCreateKey();

	let raw;
	try {
		raw = await fs.readFile(PLAIN_FILE, 'utf8');
	} catch (error) {
		if (error?.code === 'ENOENT') {
			console.error(
				`${PLAIN_FILE} does not exist.\n` +
					'Create it with one protected token per line (see the header comment in\n' +
					'this script for the format), then re-run this recipe. This file must\n' +
					'never be created inside a git working tree.',
			);
			process.exit(1);
		}
		throw error;
	}

	const rawTokens = raw
		.split('\n')
		.map((line) => line.trim())
		.filter((line) => line.length > 0 && !line.startsWith('#'));
	const normalized = rawTokens.map((line) => normalizeForConsent(line));

	const tooShort = normalized.filter((t) => t.length > 0 && t.length < MIN_TOKEN_LENGTH);
	if (tooShort.length > 0) {
		console.error(
			`${tooShort.length} token(s) in ${PLAIN_FILE} normalize to fewer than ${MIN_TOKEN_LENGTH} ` +
				'characters. Tokens that short are not enforceable by substring matching (a 1-character ' +
				'token alone would flag the overwhelming majority of files in this repo) — refusing to ' +
				"enroll them. Route bare-initial forms to editorial review instead; see the runbook's " +
				'"Naming-consent gate design" section.',
		);
		process.exit(1);
	}

	const usable = normalized.filter((t) => t.length >= MIN_TOKEN_LENGTH);
	if (usable.length === 0) {
		console.error(
			`${PLAIN_FILE} contains no usable protected tokens (>= ${MIN_TOKEN_LENGTH} chars after normalization) — refusing to write an empty gate.`,
		);
		process.exit(1);
	}

	const digests = buildHashList(usable, key);

	// Strict JSON — no comments (this file is parsed with JSON.parse, not a
	// JSONC-aware reader). The provenance/regeneration note lives in this
	// script's header instead, and in docs/runbooks/discuss-to-svx-pipeline.md.
	await fs.writeFile(OUT_FILE, `${JSON.stringify(digests, null, '\t')}\n`, 'utf8');

	// Deliberately do not print the tokens, their count-to-source mapping, or
	// anything beyond a coarse summary.
	console.log(`wrote ${path.relative(ROOT, OUT_FILE)}: ${digests.length} protected token(s) hashed.`);
}

main().catch((error) => {
	console.error(`generate-naming-consent-hashes: ${error instanceof Error ? error.message : String(error)}`);
	process.exit(1);
});
